parts.openscad_module:
$fn = 96;

wall          = 8;
housing_l     = 100;
housing_w     = 50;
housing_h     = 60;
shaft_bore_d  = 22;
bearing_seat_d = 47.025;
bearing_depth  = 14;
shaft_z        = housing_h / 2 - 10;
bolt_hole_d   = 5.5;

module gearbox_lower_half() {
  difference() {
    cube([housing_l, housing_w, housing_h/2], center = true);
    translate([0, 0, wall/2])
      cube([housing_l - 2*wall, housing_w - 2*wall, housing_h/2], center = true);
    for (x = [-housing_l/4, housing_l/4])
      translate([x, 0, shaft_z - housing_h/4])
        rotate([90, 0, 0])
          cylinder(h = housing_w + 2, d = shaft_bore_d, center = true, $fn = 64);
    for (x = [-housing_l/4, housing_l/4])
      translate([x, housing_w/2 - bearing_depth/2, shaft_z - housing_h/4])
        rotate([90, 0, 0])
          cylinder(h = bearing_depth + 0.1, d = bearing_seat_d, center = true, $fn = 96);
    for (x = [-housing_l/2 + wall, housing_l/2 - wall])
      for (y = [-housing_w/2 + wall, housing_w/2 - wall])
        translate([x, y, housing_h/4 - wall/2])
          cylinder(h = wall + 2, d = bolt_hole_d, center = true, $fn = 32);
  }
}

gearbox_lower_half();
